public class LocalDate_fromCalendarFields_TriageGen2Test {

    @Test
    public void testFromCalendarFields_AD() {
        // Test for Gregorian Calendar AD era
        Calendar calendar = new GregorianCalendar();
        calendar.set(Calendar.YEAR, 2023);
        calendar.set(Calendar.MONTH, Calendar.OCTOBER); // October is index 9
        calendar.set(Calendar.DAY_OF_MONTH, 25);
        calendar.set(Calendar.ERA, Calendar.AD);

        LocalDate expected = new LocalDate(2023, 10, 25);
        LocalDate actual = LocalDate.fromCalendarFields(calendar);

        assertEquals(expected, actual);
    }

    @Test
    public void testFromCalendarFields_BC() {
        // Test for BC era (Note: The logic in the provided method uses 1 - yearOfEra for non-AD)
        // This tests the branch: (era == GregorianCalendar.AD ? yearOfEra : 1 - yearOfEra)
        Calendar calendar = new GregorianCalendar();
        calendar.set(Calendar.YEAR, 500);
        calendar.set(Calendar.MONTH, Calendar.JANUARY);
        calendar.set(Calendar.DAY_OF_MONTH, 1);
        calendar.set(Calendar.ERA, Calendar.BC);

        // Based on the provided implementation: era != AD -> year = 1 - 500 = -499
        LocalDate expected = new LocalDate(-499, 1, 1);
        LocalDate actual = LocalDate.fromCalendarFields(calendar);

        assertEquals(expected, actual);
    }

    @Test
    public void testFromCalendarFields_LeapYear() {
        // Test edge case for leap year
        Calendar calendar = new GregorianCalendar();
        calendar.set(Calendar.YEAR, 2024);
        calendar.set(Calendar.MONTH, Calendar.FEBRUARY);
        calendar.set(Calendar.DAY_OF_MONTH, 29);
        calendar.set(Calendar.ERA, Calendar.AD);

        LocalDate expected = new LocalDate(2024, 2, 29);
        LocalDate actual = LocalDate.fromCalendarFields(calendar);

        assertEquals(expected, actual);
    }

    @Test
    public void testFromCalendarFields_YearOneAD() {
        // Test boundary year 1
        Calendar calendar = new GregorianCalendar();
        calendar.set(Calendar.YEAR, 1);
        calendar.set(Calendar.MONTH, Calendar.DECEMBER);
        calendar.set(Calendar.DAY_OF_MONTH, 31);
        calendar.set(Calendar.ERA, Calendar.AD);

        LocalDate expected = new LocalDate(1, 12, 31);
        LocalDate actual = LocalDate.fromCalendarFields(calendar);

        assertEquals(expected, actual);
    }
}
